// app/api/public/vending-slots/route.ts — Public Dynamic 12-Slot Vending Floor API
// Relational Slot Authority (Phase 4.1 & 4.2): Backed by PostgreSQL vending_slots table.
// Supersedes legacy JSON setting vending_machine_slots; integrates CatalogService.getLiveStockMap via VendingSlotService.
import { NextResponse } from "next/server";
import { VendingSlotService } from "@/src/services/vending-slot.service";
import { checkRateLimit, RATE_LIMIT_TIERS } from "@/src/services/rate-limiter.service";
import { getClientIp } from "@/app/lib/ip";

export const dynamic = "force-dynamic";
export const revalidate = 0;

export async function GET(request?: Request) {
  try {
    const ip = getClientIp(request);
    const limit = await checkRateLimit(`slots:ip:${ip}`, RATE_LIMIT_TIERS.public);
    if (!limit.allowed) {
      return NextResponse.json({ error: "Rate limit exceeded" }, { status: 429 });
    }

    const slots = await VendingSlotService.getPublicSlots();

    // Map to canonical DTO with backward-compatible aliases for legacy floor consumers
    const formattedSlots = slots.map((s) => ({
      ...s,
      slot: s.slotCode,
      product: s.displayTitle || s.productName,
      subtitle: s.tierSubtitle || s.subtitle,
      tier: s.tierSubtitle || s.subtitle,
      skin: s.skinId,
      price: s.price,
      stock: s.stock,
      sortOrder: s.sortOrder,
      skinConfig: s.skinConfig,
    }));

    return NextResponse.json(
      {
        success: true,
        count: formattedSlots.length,
        slots: formattedSlots,
        data: formattedSlots,
      },
      {
        headers: {
          "Cache-Control": "public, s-maxage=5, stale-while-revalidate=15",
        },
      }
    );
  } catch (err: any) {
    console.error("[Public Vending Slots GET] Error:", err?.message || err);
    return NextResponse.json(
      {
        success: false,
        error: "Vending floor service temporarily unavailable",
        code: "SLOTS_UNAVAILABLE",
        count: 0,
        slots: [],
        data: [],
      },
      { status: 503 }
    );
  }
}

