static invalidateCache(): void {
  _cachedPublicSlots = null;
}

static async getPublicSlots(bypassCache = false): Promise<VendingSlotDTO[]> {
  const now = Date.now();
  if (!bypassCache && _cachedPublicSlots && _cachedPublicSlots.expiresAt > now) {
    return _cachedPublicSlots.data;
  }

  const pool = getPool();
  const [slotRows, stockMap] = await Promise.all([
    pool.query<any>(`
      SELECT s.slot_code, s.product_id, s.variant_id, s.display_title, s.tier_subtitle,
        s.skin_id, s.category, s.enabled, s.revision, s.sort_order, s.icon_url AS slot_icon_url,
        p.name AS product_name, COALESCE(p.subtitle, '') AS product_subtitle, p.icon_url AS product_icon_url, p.status AS product_status,
        p.visibility AS product_visibility, p.manual_stock_override, p.manual_stock_count, p.stock_status,
        p.is_supplier_synced, p.supplier_id, p.stock AS product_stock,
        COALESCE(p.fulfillment_type, 'CREDENTIALS') AS fulfillment_type,
        v.name AS variant_name, v.price AS variant_price,
        v.enabled AS variant_enabled, v.stock_override AS variant_stock_override,
        v.description AS variant_description,
        sk.name AS skin_name, sk.group_name AS skin_group_name, sk.accent_color, sk.glow_color, sk.border_color,
        sk.primary_gradient, sk.secondary_gradient, sk.chamber_gradient,
        sk.font_family, sk.font_spec, sk.canopy_text, sk.canopy_icon, sk.badge_text, sk.button_text, sk.chamber_style, sk.is_builtin AS skin_is_builtin
      FROM vending_slots s
      LEFT JOIN products p ON p.id = s.product_id AND p.archived_at IS NULL
      LEFT JOIN variants v ON v.product_id = s.product_id AND v.id = s.variant_id
      LEFT JOIN vending_skins sk ON sk.id = s.skin_id
      ORDER BY s.sort_order ASC, s.slot_code ASC
    `),
    CatalogService.getLiveStockMap(),
  ]);

  const mapped = slotRows.rows.map((r: any): VendingSlotDTO => {
    const slotCode = String(r.slot_code);
    const revision = Number(r.revision || 1);
    const sortOrder = Number(r.sort_order || 0);
    const productId = r.product_id ? Number(r.product_id) : null;
    const variantId = r.variant_id ? Number(r.variant_id) : null;
    const rawSlotEnabled = Boolean(r.enabled);
    const isProductValid = Boolean(
      productId &&
      variantId &&
      r.product_name &&
      r.product_status !== "DISABLED" &&
      (!r.product_visibility || r.product_visibility === "VISIBLE" || rawSlotEnabled) &&
      r.variant_enabled !== false
    );
    const effectiveEnabled = Boolean(rawSlotEnabled && isProductValid);
    const rawSlotTitle = r.display_title ? String(r.display_title).trim() : "";
    const rawProductName = r.product_name ? String(r.product_name).trim() : "";
    const displayTitle = rawSlotTitle || rawProductName || "Unassigned";
    const productName = rawProductName || rawSlotTitle || "Unassigned";

    const rawSlotSubtitle = r.tier_subtitle !== undefined && r.tier_subtitle !== null ? String(r.tier_subtitle).trim() : "";
    const productSubtitle = r.product_subtitle !== undefined && r.product_subtitle !== null ? String(r.product_subtitle).trim() : "";
    const variantName = r.variant_name && r.variant_name !== r.product_name ? String(r.variant_name).trim() : "";
    const tierSubtitle = rawSlotSubtitle || productSubtitle || variantName;

    const skinId = String(r.skin_id || "sakura");
    const category = r.category as SlotCategory;
    const durationLabel = rawSlotSubtitle || productSubtitle || variantName || (r.variant_name ? String(r.variant_name).trim() : "");
    const priceNumber = r.variant_price !== null && r.variant_price !== undefined ? Number(r.variant_price) : 0;
    const priceMinor = Math.round(priceNumber * 100);
    const isManual = Boolean(
      r.manual_stock_override ||
      r.stock_status === "MANUAL_OVERRIDE" ||
      (r.manual_stock_count !== null && r.manual_stock_count !== undefined && r.stock_status !== "AUTO_VAULT")
    );
    const manualStock = Number(r.manual_stock_count ?? 0);
    const isSupplierProduct = Boolean(r.is_supplier_synced || r.supplier_id);
    const liveStock = productId
      ? isSupplierProduct
        ? Number(r.product_stock ?? stockMap.get(productId) ?? 0)
        : (stockMap.get(productId) ?? 0)
      : 0;
    const baseStock = isManual ? manualStock : liveStock;
    const effectiveStock = r.variant_stock_override !== null && r.variant_stock_override !== undefined ? Number(r.variant_stock_override) : baseStock;
    let purchasable = false;
    let reason: string | null = null;
    if (!rawSlotEnabled) reason = "Slot disabled";
    else if (!productId || !variantId || !r.product_name) reason = "Slot unbound";
    else if (r.product_status === "DISABLED" || (r.product_visibility && r.product_visibility !== "VISIBLE" && !rawSlotEnabled)) reason = "Product unavailable";
    else if (r.variant_enabled === false) reason = "Variant disabled";
    else if (effectiveStock <= 0) reason = "Sold out";
    else if (priceMinor <= 0) reason = "Invalid price";
    else purchasable = true;
    const iconUrl = normalizeIconUrl(r.slot_icon_url) || normalizeIconUrl(r.product_icon_url);

    const skinConfig: VendingSkinDTO | null = r.accent_color ? {
      id: skinId,
      name: r.skin_name || skinId,
      groupName: r.skin_group_name || "custom",
      accentColor: r.accent_color,
      glowColor: r.glow_color,
      borderColor: r.border_color,
      primaryGradient: r.primary_gradient,
      secondaryGradient: r.secondary_gradient,
      chamberGradient: r.chamber_gradient,
      fontFamily: r.font_family || "Inter",
      fontSpec: r.font_spec,
      canopyText: r.canopy_text || "✦ VEND TERMINAL ✦",
      canopyIcon: r.canopy_icon,
      badgeText: r.badge_text || "★",
      buttonText: r.button_text || "VEND NOW",
      chamberStyle: r.chamber_style || "clear",
      isBuiltin: Boolean(r.skin_is_builtin),
    } : null;

    return {
      slotCode, revision, sortOrder, productId, variantId, productName, displayTitle, tierSubtitle, subtitle: tierSubtitle,
      skinId, category,
      iconUrl: iconUrl || null,
      icon: iconUrl ? { kind: "image", src: iconUrl, alt: productName || displayTitle } : { kind: "builtin", key: (productName || displayTitle).toLowerCase().replace(/[^a-z0-9]+/g, "-") },
      durationLabel, currency: "PHP", priceMinor, price: priceNumber, stock: effectiveStock,
      enabled: effectiveEnabled,
      slotEnabled: rawSlotEnabled,
      purchasable, reason,
      description: r.variant_description || null,
      skinConfig,
      fulfillmentType: String(r.fulfillment_type || "CREDENTIALS"),
    };
  });

  _cachedPublicSlots = { data: mapped, expiresAt: now + PUBLIC_SLOTS_CACHE_TTL_MS };
  return mapped;
}

